{
  "name": "opencode-quill",
  "version": "0.7.0",
  "description": "OpenCode prompt autocomplete: local n-gram word and next-word prediction shown as inline ghost text in the TUI composer, accepted with Tab.",
  "type": "module",
  "license": "MIT",
  "author": "Ozan Dogrultan",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ozandogrultan/opencode-quill.git"
  },
  "homepage": "https://github.com/ozandogrultan/opencode-quill#readme",
  "bugs": {
    "url": "https://github.com/ozandogrultan/opencode-quill/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "autocomplete",
    "autosuggest",
    "ngram",
    "prompt",
    "word-prediction",
    "opencode-tui"
  ],
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "tsconfig.json",
    "CHANGELOG.md",
    "LICENSE",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "packageManager": "bun@1.4.2",
  "engines": {
    "opencode": ">=2.2.3"
  },
  "scripts": {
    "prepare": "husky",
    "test": "bun test && bash tests/changelog.sh",
    "test:unit": "bun test",
    "test:changelog": "bash tests/changelog.sh",
    "typecheck": "tsc --noEmit",
    "lint:sh": "for script in install.sh tests/*.sh scripts/*.sh; do bash -n \"$script\" || exit; done",
    "prepublishOnly": "bun run test && bun run typecheck"
  },
  "dependencies": {
    "@opentui/core": "^0.8.1",
    "@opentui/solid": "^0.8.1",
    "subtlex-word-frequencies": "2.0.0"
  },
  "peerDependencies": {
    "@opencode/plugin": "*",
    "solid-js": "*"
  },
  "devDependencies": {
    "@commitlint/cli": "^21.2.2",
    "@commitlint/config-conventional": "^21.2.2",
    "@opencode/plugin": "2.2.6",
    "@types/bun": "^1.4.2",
    "@types/node": "26.6.6",
    "husky": "^9.1.7",
    "solid-js": "1.9.12",
    "typescript": "7.0.2"
  }
}
